import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useParams } from 'react-router-dom';

import cn from 'classnames';

import { EVerificationOpenForm, useGetSourceQuery, VerificationForm } from 'entities/Source';
import { EFilters, useFilters } from 'features/Filters';
import { useNotFoundError } from 'shared/hooks';
import { OverlayLoader, Page, PageTitle } from 'shared/ui';

import styles from './VerificateSource.module.scss';

interface IVerificateSourceProps extends HTMLAttributes<HTMLDivElement> {}

export const VerificateSource: FC<IVerificateSourceProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const params = useParams<{ id: string }>();
	const { getFilterValue } = useFilters();
	const { data, error, isFetching } = useGetSourceQuery(params?.id || '');

	useNotFoundError(error);

	return (
		<Page {...props} className={cn(className, styles.verificateSource)}>
			<PageTitle subtitle={t('Это необходимо, чтобы вы смогли подавать заявки на оффера рекламодателей.')}>
				{t('Подтверждение владения {{sourceName}}', { sourceName: data?.name })}
			</PageTitle>

			{isFetching && <OverlayLoader />}

			<VerificationForm
				className={styles.form}
				source={data}
				isAdding={getFilterValue(EFilters.OPEN) === EVerificationOpenForm.CREATE}
			/>
		</Page>
	);
};

export default VerificateSource;
